import java.util.List;
import java.util.Random;

/**
 * This is an abstract class representing all the species of
 * the simulation. It defines some characteristics and methods
 * of the species.
 *
 * @version 2022.02.28
 */
public abstract class Species
{
    // The probability for an individual to die if exposed to too high or too cold temperatures. Can be adjusted for simulation realism purposes.
    private static final double DYING_OF_COLD_OR_HEAT_PROBABILITY = 0.8;
    // Whether the species is alive or not.
    private boolean alive;
    // The animal's field.
    private Field field;
    // The species' position in the field.
    private Location location;
    // The species' name
    private final String name;
    // The maximum temperature at which the species can survive
    private final int maximumTemperature;
    // The minimum temperature at which the species can survive
    private final int minimumTemperature;
    // The food value animal provides when eaten
    private final int nutritionalValue;
    // The likelihood of a specie to reproduce.
    private final double reproductionProbability;
    // A random number generator
    protected static final Random rand = Randomizer.getRandom();

    /**
     * Create a new specie at location in field.
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the specie
     * @param maximumTemperature (int) The maximum temperature that the specie can withstand
     * @param minimumTemperature (int) The minimum temperature that the specie can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this specie
     * @param reproductionProbability (double) The probability that this specie will reproduce
     */
    public Species(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability)
    {
        alive = true;
        this.field = field;
        setLocation(location);
        this.name = name;
        this.maximumTemperature = maximumTemperature;
        this.minimumTemperature = minimumTemperature;
        this.nutritionalValue = nutritionalValue;
        this.reproductionProbability = reproductionProbability;
    }

    /**
     * Make this animal act - that is: make it do whatever it wants/needs to do.
     *
     * @param newSpecies (List<Species>) A list to receive newly born animals.
     * @param isNight (boolean) If it is currently night.
     * @param yearPassed (boolean) If a year is passing on this step (next step is the first of a nw year).
     */
    abstract public void act(List<Species> newSpecies, boolean isNight, int temperature, boolean yearPassed);

    /**
     * An abstract class to enforce all subclasses to make their elements reproduce
     *
     * @param newOfThisKind List of Species objects in the simulation for the newborns to be added to it
     */
    abstract void reproduce(List<Species> newOfThisKind);

    /**
     * Create a newborn species of the current kind.
     *
     * @param location the location at which the newborn should appear.
     * @return the newborn species.
     */
    protected abstract Species createOffspring(Location location);

    /**
     * Create newborn species in the provided free locations.
     *
     * @param speciesInSimulation the list receiving newborn species.
     * @param freeLocations the available locations for newborns.
     * @param births the number of newborns to create.
     */
    protected final void reproduceAtFreeLocations(List<Species> speciesInSimulation, List<Location> freeLocations, int births)
    {
        for (int birth = 0; birth < births && !freeLocations.isEmpty(); birth++) {
            Location loc = freeLocations.remove(0);
            speciesInSimulation.add(createOffspring(loc));
        }
    }

    /**
     * Check whether the animal is alive or not.
     *
     * @return (boolean) true if the animal is still alive.
     */
    protected boolean isAlive()
    {
        return alive;
    }

    /**
     * Indicate that the animal is no longer alive. It is removed from the field.
     */
    protected void setDead()
    {
        alive = false;
        if(location != null) {
            field.clear(location);
            location = null;
            field = null;
        }
    }

    /**
     * Return the animal's location.
     *
     * @return (Location)The animal's location.
     */
    protected Location getLocation()
    {
        return location;
    }

    /**
     * Place the animal at the new location in the given field.
     *
     * @param newLocation (Location) The animal's new location.
     */
    protected void setLocation(Location newLocation)
    {
        if(location  != null) {
            field.clear(location);
        }
        location = newLocation;
        field.place(this, newLocation);
    }

    /**
     * @return (Field) The animal's field.
     */
    protected Field getField()
    {
        return field;
    }

    /**
     * Check whether the current temperature is lethal for this species.
     * If temperature is too low or too high, the species has a high probability of dying.
     *
     * @param temperature the current temperature.
     * @return true if the temperature is lethal.
     */
    protected boolean isTemperatureLethal(int temperature)
    {
        if (temperature > maximumTemperature || temperature < minimumTemperature) {
            return rand.nextDouble() <= DYING_OF_COLD_OR_HEAT_PROBABILITY;
        }
        return false;
    }

    /**
     * Handle death caused by temperature exposure.
     * Subclasses can override this to preserve additional state.
     */
    protected void onTemperatureDeath()
    {
        setDead();
    }

    /**
     * @return (String) The specie's name.
     */
    protected String getName()
    {
        return name;
    }

    /**
     * @return (int) The maximum temperature specie can survive to.
     */
    protected int getMaximumTemperature()
    {
        return maximumTemperature;
    }

    /**
     * @return (int) The minimum temperature specie can survive to.
     */
    protected int getMinimumTemperature()
    {
        return minimumTemperature;
    }

    /**
     * @return (int) The specie's nutritional value.
     */
    protected int getNutritionalValue()
    {
        return nutritionalValue;
    }

    /**
     * @return (double) The specie's reproduction probability.
     */
    protected double getReproductionProbability()
    {
        return reproductionProbability;
    }

}

import java.util.List;

/**
 * A class representing plants in the simulation. It extends
 * the abstract class Species
 *
 * @version 2022.02.28
 */
public class Plant extends Species
{
    // The plant's maximum health
    private int maxHealth;
    // The probability that the plant's health grows
    private static final double GROWING_PROBABILITY = 0.1;
    // Keep track of the plant's health
    private int currentHealth;
    // true if the current season is Spring
    private boolean isSpring;
    // true if the plant can regrow, needs at least one season till it is true again
    private boolean canRegrow;
    // true if plant appears dead due to temperature circumstances
    private boolean deadDueTemperature;

    /**
     * Create an instance of Plant
     *
     * @param field (Field) The field currently occupied.
     * @param location (Location) The location within the field.
     * @param name (String) The name of the plant
     * @param maximumTemperature (int) The maximum temperature that the plant can withstand
     * @param minimumTemperature (int) The minimum temperature that the plant can withstand
     * @param nutritionalValue (int) The nutritional value given to the specie that eats this plant
     * @param reproductionProbability (double) The probability that this plant will reproduce
     * @param maxHealth (int) The plant's maximum health
     */
    public Plant(Field field, Location location, String name, int maximumTemperature, int minimumTemperature, int nutritionalValue, double reproductionProbability, int maxHealth)
    {
        super(field, location, name, maximumTemperature, minimumTemperature, nutritionalValue, reproductionProbability);
        this.maxHealth = maxHealth;
        currentHealth = maxHealth;
        isSpring = true;
        canRegrow = true;
        deadDueTemperature = false;
    }

    /**
     * Imitate a plant's step by doing the following:
     * 1) if the plant can't survive the temperature, then it dies
     * 2) else if the time is day:
     *      i) if the plant is dead, and it's spring, and the temperature is suitable,
     *         then grow back
     *      ii) else if the plant is alive, then
     *          a) increase max health by 1 if it lived for a year
     *          b) reproduce and grow
     *
     * @param newPlants (List<Species>) A list to return the new plants created.
     * @param isNight (boolean) true if it is night in the simulation
     * @param temperature (int) The current temperature of the simulation
     * @param yearPassed (boolean) True if a year has passed in the simulation
     */
    public void act(List<Species> newPlants, boolean isNight, int temperature, boolean yearPassed)
    {
        // 1)
        if (!deadDueTemperature && isTemperatureLethal(temperature))
        {
            onTemperatureDeath();
        }
        // 2)
        else if (! isNight)
        {
            // i)
            if (deadDueTemperature && !isTemperatureLethal(temperature) && isSpring) {
                regrow();
            }
            // ii)
            else if (! deadDueTemperature) {
                // a)
                if (yearPassed) {
                    maxHealth++;
                }
                // b)
                reproduce(newPlants);
                grow();
            }
        }
    }

    /**
     * Add a new plant in a free neighbouring location if the two
     * following conditions are met:
     * 1- The production probability meets the random number
     * 2- There is a free adjacent location.
     *
     * @param newPlants (list<Species>)A list to return the new plant
     */
    protected void reproduce(List<Species> newPlants)
    {
        Field field = getField();
        if (field != null && rand.nextDouble() <= getReproductionProbability()) {
            reproduceAtFreeLocations(newPlants, field.getFreeAdjacentLocations(getLocation()), 1);
        }
    }

    /**
     * Create a newborn plant of the current species.
     *
     * @param location the location at which the newborn should appear.
     * @return the newborn plant.
     */
    @Override
    protected Species createOffspring(Location location)
    {
        Plant newPlant = new Plant(getField(), location, getName(), getMaximumTemperature(), getMinimumTemperature(), getNutritionalValue(), getReproductionProbability(), maxHealth);
        newPlant.setIsSpring(isSpring);
        return newPlant;
    }

    /**
     * The plant dies because of the temperature.
     * Its location in the field is cleared, but it still remembers its field and location.
     */
    @Override
    protected void onTemperatureDeath()
    {
        if(getLocation() != null) {
            deadDueTemperature = true;
            canRegrow = false; // set to false because if left as true, it could regrow the next step
            getField().clear(getLocation());
        }
    }

    /**
     * The dead plant is placed back in the field if its previous location is empty and can regrow, otherwise do nothing.
     * If it grows, then it grows back to full health.
     */
    private void regrow()
    {
        if(getField().getObjectAt(getLocation()) == null && canRegrow)   {
            deadDueTemperature = false;
            getField().place(this, getLocation());
            currentHealth = maxHealth;
        }
    }

    /**
     * Increase the plant's health by one if the random number meets the growing probability
     */
    private void grow()
    {
        if (currentHealth < maxHealth && rand.nextDouble() <= GROWING_PROBABILITY) {
            currentHealth++;
        }
    }

    /**
     * The effect of getting eaten by an animal.
     * Decrement currentHealth by one, and set dead if the current health is less than 1.
     */
    public void isEaten()
    {
        currentHealth--;

        if (currentHealth <= 0)    {
            super.setDead();
        }
    }

    /**
     * If isSpring is true, then change it to false, vice versa.
     *Also, set canRegrow as true because at least a season has passed since the plant died.
     */
    public void toggleIsSpring()
    {
        isSpring = ! isSpring;
        canRegrow = true;
    }

    /**
     * @return (boolean) true if the current season is spring, false otherwise.
     */
    public boolean getIsSpring()
    {
        return isSpring;
    }

    /**
     * Set the isSpring value to the given parameter
     *
     * @param spring (boolean) true if it is spring, false otherwise.
     */
    private void setIsSpring(boolean spring)
    {
        isSpring = spring;
    }
}

